INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 28, 'theory', 'Quiz: advanced SQL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 0, 'How does a window function differ from grouping with an aggregate?', '["A window function adds a value to each row without collapsing them into one per group", "A window function works only with text", "Window functions are forbidden in SELECT", "Grouping cannot sum"]', 0, 'With a window you can show an order row and the customer''s order total side by side; GROUP BY would leave one row per customer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 1, 'How do you get the three most expensive products in each category?', '["Use LIMIT 3 once", "Do GROUP BY category and take the maximum", "Number the rows with ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC) in a subquery and keep numbers up to three", "Sort the table and hope for the order"]', 2, 'Windows are computed after WHERE, so the condition on the number is put in a wrapper or a common expression.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 2, 'What does the frame ROWS BETWEEN 2 PRECEDING AND CURRENT ROW do?', '["Sums the whole table", "Picks two random rows", "Removes duplicates", "Takes the current row and the two preceding ones — for example, for a three-step moving average"]', 3, 'ROWS counts physical rows, RANGE counts order values; with equal values they give different results.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 3, 'What parts does a recursive common expression consist of, and how do you avoid an infinite loop?', '["Only the anchor; there are no cycles", "The anchor and the recursive step joined with UNION ALL; with a cycle in the data, limit the depth, remember the path or use UNION", "Two independent queries", "An index and a trigger"]', 1, 'Recursion stops when the step yields no new rows; with a cycle in the data and no protection it never ends.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 28, 4, 'Why is NOT EXISTS more reliable than NOT IN for finding customers without orders?', '["NOT IN is always faster", "NOT EXISTS does not work without an index", "If the NOT IN subquery meets a NULL, it returns no rows at all, while NOT EXISTS behaves as expected", "NOT EXISTS is forbidden by the standard"]', 2, 'Comparison with NULL gives «unknown», so NOT IN with a NULL in the list filters out all rows.');
